param([switch]$Check)
$ErrorActionPreference = 'Stop'
$fpgaRoot = Split-Path $PSScriptRoot -Parent
$mapDir = Join-Path $fpgaRoot 'assets/maps'
$definitions = Get-Content (Join-Path $mapDir 'tiles.json') -Raw | ConvertFrom-Json
if ($definitions.format_version -ne 1) { throw 'Unsupported tile definition format' }
$ids = @{}
$palette = @(
    '// Generated by FPGA/tools/generate_maps.ps1; edit assets/maps/tiles.json.'
    '// Terrain semantics are metadata for a future MCU exporter, not FPGA physics.'
    'module tile_palette (input logic [7:0] tile_id, output logic [23:0] rgb);'
    '    always_comb begin'
    '        case (tile_id)'
)
foreach ($tile in $definitions.tiles) {
    if ($tile.id -isnot [int] -or $tile.id -lt 0 -or $tile.id -gt 255 -or $ids.ContainsKey($tile.id)) {
        throw 'Tile IDs must be unique bytes'
    }
    if ($tile.rgb -notmatch '^[0-9a-fA-F]{6}$') { throw 'Tile color must be six hex digits' }
    $ids[$tile.id] = $true
    $palette += "            8'd$($tile.id): rgb = 24'h$($tile.rgb);"
}
$palette += @("            default: rgb = 24'hff00ff; // Invalid ID is visible during bring-up."
             '        endcase', '    end', 'endmodule')
$outputs = @{}
$outputs[(Join-Path $fpgaRoot 'rtl/tile_palette.sv')] = ($palette -join "`n") + "`n"
foreach ($file in Get-ChildItem $mapDir -Filter '*.json') {
    if ($file.Name -eq 'tiles.json') { continue }
    $map = Get-Content $file.FullName -Raw | ConvertFrom-Json
    if ($map.format_version -ne 1 -or $map.tile_size -ne 16 -or $map.columns -ne 40 -or $map.rows -ne 30) {
        throw "Unsupported map geometry or version: $($file.Name)"
    }
    if ($map.map_id -isnot [int] -or $map.map_id -lt 0 -or $map.map_id -gt 65535 -or
        $map.map_version -isnot [int] -or $map.map_version -lt 1) { throw 'Invalid map identity' }
    if ($map.start.x -lt 0 -or $map.start.x -ge 640 -or $map.start.y -lt 0 -or $map.start.y -ge 480 -or
        $map.start.heading_degrees -lt 0 -or $map.start.heading_degrees -ge 360) { throw 'Invalid start pose' }
    foreach ($gate in @($map.finish) + @($map.checkpoints)) {
        if ($gate.axis -notin @('x', 'y') -or $gate.direction -notin @(-1, 1) -or $gate.span.Count -ne 2) {
            throw 'Invalid gate definition'
        }
        $along = if ($gate.axis -eq 'x') { 640 } else { 480 }
        $across = if ($gate.axis -eq 'x') { 480 } else { 640 }
        if ($gate.position -lt 0 -or $gate.position -ge $along -or
            $gate.span[0] -lt 0 -or $gate.span[1] -gt $across -or $gate.span[0] -ge $gate.span[1]) {
            throw 'Gate outside display'
        }
    }
    if ($map.tiles.Count -ne 30) { throw 'Map must have 30 rows' }
    $lines = foreach ($row in $map.tiles) {
        if ($row.Count -ne 40) { throw 'Map rows must have 40 tiles' }
        $bytes = foreach ($id in $row) {
            if ($id -isnot [int] -or !$ids.ContainsKey($id)) { throw "Undefined tile ID: $id" }
            '{0:x2}' -f $id
        }
        $bytes -join ' '
    }
    $outputs[(Join-Path $mapDir ($file.BaseName + '.mem'))] = ($lines -join "`n") + "`n"
}
foreach ($path in $outputs.Keys) {
    if ($Check) {
        if (!(Test-Path $path) -or (Get-Content $path -Raw).Replace("`r`n", "`n") -cne $outputs[$path]) {
            throw "Generated asset missing or stale: $path"
        }
    } else {
        [IO.File]::WriteAllText($path, $outputs[$path], [Text.UTF8Encoding]::new($false))
    }
}
Write-Output "PASS: map definitions validated; $($outputs.Count) generated assets $(if ($Check) {'checked'} else {'written'})"
